# Check SUMMARYPAGE and INFOTABLE value description in metadata
python3 << 'EOF'
import json
with open('/root/2025-q3/FORM13F_metadata.json') as f:
    data = json.load(f)

for table in data['tables']:
    if table['url'] in ['SUMMARYPAGE.tsv', 'INFOTABLE.tsv']:
        print(f"\n=== {table['url']} ===")
        for col in table['tableSchema']['columns']:
            if 'value' in col['name'].lower() or 'VALUE' in col['name']:
                print(f"  {col['name']}: {col.get('dc:description', 'no desc')}")
EOF
